mapper.select:
SELECT

FROM sys_user u
LEFT JOIN sys_dept d ON u.dept_id = d.id AND d.deleted = 0


        AND u.username LIKE CONCAT('%', #{q.username}, '%')


        AND u.real_name LIKE CONCAT('%', #{q.realName}, '%')


        AND u.phone LIKE CONCAT('%', #{q.phone}, '%')


        AND u.status = #{q.status}


        AND u.dept_id = #{q.deptId}



        ${dataScope}


ORDER BY u.id ASC
